function week(){const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Australia/Brisbane',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);const today=new Date(parts+'T12:00:00+10:00');const monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7));return `<div class="week">${Array.from({length:7},(_,i)=>{const day=new Date(monday);day.setDate(monday.getDate()+i);return `<div class="day ${fmt(day)===fmt(today)?'today':''}">${fmt(day,{weekday:'narrow'})}<strong>${fmt(day,{day:'numeric'})}</strong><div class="mini-dot"></div></div>`;}).join('')}</div>`;}
function scopeForPage(){return {clients:'clients',projects:'projects',contracts:'contracts',marketing:'posts',prospects:'prospects',notes:'notes',finance:'invoices',library:'documents',assets:'media',technology:'resources',meetings:'meetingNotes',renewals:'renewals',onboarding:'onboardings',reports:'reportSchedules',forecast:'forecastItems',time:'profitabilityProjects'}[page]||'';}
function ensureListScope(scope){if(scope&&scope!==listScope){listScope=scope;listCondition='';listCategory='';activeListViewId='';}}
function viewRecords(collection,list){if(scopeForPage()===collection)ensureListScope(collection);return applyListView(collection,list,{query:search,status:filter,category:scopeForPage()===collection?listCategory:'',condition:scopeForPage()===collection?listCondition:''},data);}
function listViewControls(scope){if(!scope)return '';
 ensureListScope(scope);const views=(data.listViews||[]).filter(v=>v.scope===scope);
 const quick=scope==='prospects'?['notContacted7Days','Not contacted in 7 days']:scope==='invoices'?['overdue','Overdue invoices']:null;
 return `<div class="list-view-controls" role="group" aria-label="Saved views"><button type="button" class="view-pill ${!listCondition&&!activeListViewId&&!filter&&!search&&!listCategory?'active':''}" data-list-reset>All</button>${quick?`<button type="button" class="view-pill ${listCondition===quick[0]?'active':''}" data-list-condition="${quick[0]}">${quick[1]}</button>`:''}${scope==='documents'?`<select id="list-category" aria-label="Document category"><option value="">All categories</option>${['PRD','Contract','Policy','Template','Procedure','Brand','Other'].map(c=>`<option value="${c}" ${listCategory===c?'selected':''}>${c}</option>`).join('')}</select><select id="list-status" aria-label="Document status">${['All','Draft','Current','Archived'].map(c=>`<option value="${c==='All'?'':c}" ${(filter||'All')===c?'selected':''}>${c}</option>`).join('')}</select>`:''}${views.map(v=>`<span class="saved-view-pair"><button type="button" class="view-pill ${activeListViewId===v.id?'active':''}" data-list-view="${esc(v.id)}">${esc(v.name)}</button><button type="button" class="saved-view-remove" data-remove-list-view="${esc(v.id)}" aria-label="Remove saved view ${esc(v.name)}">×</button></span>`).join('')}<button type="button" class="view-pill save-view" data-save-list-view="${scope}">+ Save view</button></div>`;
}
function toolbar(tabs=[]){const scope=scopeForPage();return `<div class="toolbar">${tabs.length?`<div class="page-tabs" role="group" aria-label="Filter">${tabs.map(t=>`<button type="button" data-filter="${t}" class="${(filter||tabs[0])===t?'active':''}" aria-pressed="${(filter||tabs[0])===t}">${t}</button>`).join('')}</div>`:'<span></span>'}<div class="search">${icon('search')}<input id="record-search" type="search" aria-label="Search records" placeholder="Search…" value="${esc(search)}"></div>${listViewControls(scope)}</div>`;}
function records(collection){return viewRecords(collection,data[collection]||[]);}
function clients(){if(operations.hasClient())return operations.client();const list=records('clients');return heading('RELATIONSHIPS','Good business starts with people.','Every client, conversation and detail in one place.',addButton('clients','New client'))+toolbar(['All','Lead','Active','Past'])+panel('Your clients',`${list.length} relationships`,list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Client</th><th>Contact</th><th>Status</th><th>Projects</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><button class="link title-cell" data-client="${c.id}">${esc(c.name)}</button><small>${esc(c.company||'Independent client')}</small></td><td>${esc(c.email||'—')}<small>${esc(c.phone)}</small></td><td>${badge(c.status)}</td><td>${data.projects.filter(p=>p.clientId===c.id).length}</td><td><button class="icon-btn" data-edit="clients:${c.id}" aria-label="Edit ${esc(c.name)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('users','Build your circle','Add a client and give their work a place to live.',addButton('clients','Add a client')));}
function projects(){const list=records('projects');return heading('FROM IDEA TO DONE','Make good things happen.','Projects, timelines and the steps that move them forward.',addButton('projects','New project'))+toolbar(['All','Planning','Active','Complete'])+`<div class="cards">${list.map(p=>{const tasks=data.tasks.filter(t=>t.projectId===p.id),done=tasks.filter(t=>t.status==='Done').length;return `<section class="panel"><div class="card-body"><div class="card-top"><div><button class="link" data-edit="projects:${p.id}"><h2>${esc(p.name)}</h2></button><div class="row-sub">${esc(clientName(p.clientId))}</div></div>${badge(p.status)}</div><p>${esc(p.description||'Add a description to give this project a clear direction.')}</p><div class="progress-track"><div class="progress-fill" style="width:${tasks.length?done/tasks.length*100:0}%"></div></div><div class="row-sub">${done} of ${tasks.length} tasks complete</div>${tasks.slice(0,5).map(t=>`<div class="list-row"><div class="row-info"><button class="check ${t.status==='Done'?'done':''}" data-complete="${t.id}" aria-label="Toggle ${esc(t.title)}">${t.status==='Done'?icon('check'):''}</button><button class="link" data-edit="tasks:${t.id}">${esc(t.title)}</button></div><span class="row-sub">${fmt(t.dueDate)}</span></div>`).join('')}</div><div class="card-footer"><span>${fmt(p.startDate)} → ${fmt(p.dueDate)}</span><button class="text-btn" data-task-project="${p.id}">Add task +</button></div></section>`;}).join('')}</div>`+(!list.length?panel('Your projects','Keep everything moving',empty('folder','A fresh start for your next idea','Set a timeline, break it into tasks and connect it to a client.',addButton('projects','Create a project'))):'')+panel('All tasks',`${data.tasks.filter(t=>t.status!=='Done').length} still to do`,`<div class="panel-body">${data.tasks.length?data.tasks.map(t=>`<div class="list-row"><div class="row-info"><button class="check ${t.status==='Done'?'done':''}" data-complete="${t.id}" aria-label="Toggle ${esc(t.title)}">${t.status==='Done'?icon('check'):''}</button><div><button class="link" data-edit="tasks:${t.id}">${esc(t.title)}</button><div class="row-sub">${esc(projectName(t.projectId))} · ${fmt(t.dueDate)}</div></div></div>${badge(t.status)}</div>`).join(''):empty('check','Every step counts','Add your first task to get moving.')}</div>`,`<button class="text-btn" data-new="tasks">New task +</button>`)+timeline();}
function timeline(){const list=data.projects.filter(p=>p.startDate&&p.dueDate);if(!list.length)return '';const min=Math.min(...list.map(p=>Date.parse(p.startDate))),max=Math.max(...list.map(p=>Date.parse(p.dueDate))),span=Math.max(max-min,86400000);return panel('Project timeline',`${fmt(min)} — ${fmt(max)}`,`<div class="timeline-chart">${list.map(p=>`<div class="timeline-project"><span>${esc(p.name)}</span><div><div class="timeline-bar" style="margin-left:${(Date.parse(p.startDate)-min)/span*60}%;width:${Math.max(20,(Date.parse(p.dueDate)-Date.parse(p.startDate))/span*100)}%;max-width:100%">${fmt(p.dueDate)}</div></div></div>`).join('')}</div>`);}
function contracts(){const list=records('contracts');return heading('AGREEMENTS & NEXT STEPS','Keep every agreement in view.','From first draft to signed and ready to go.',addButton('contracts','New contract'))+toolbar(['All','Draft','Sent','Awaiting signature','Signed'])+`<div class="notice">Contract stages are tracked locally. Add a document link to open your agreement. Signature collection and automatic status updates need a signing-service connection.</div>`+panel('Your contracts',`${list.length} agreements`,list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Agreement</th><th>Client</th><th>Value</th><th>Stage</th><th>Follow-up</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><button class="link title-cell" data-edit="contracts:${c.id}">${esc(c.title)}</button><small>${esc(projectName(c.projectId))}</small></td><td>${esc(clientName(c.clientId))}</td><td>${currency(c.value)}</td><td>${badge(c.status)}</td><td>${fmt(c.dueDate)}</td><td>${c.documentUrl?`<a class="icon-btn" href="${esc(c.documentUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Open contract">${icon('external')}</a>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('file','Good work starts with clear agreements','Track an agreement from draft through to signature.',addButton('contracts','Add a contract')));}
function marketing(){const list=records('posts');return heading('CREATE. PLAN. CONNECT.','Make a little more impact.','Your ideas, drafts and content calendar, together.',addButton('posts','Create content'))+toolbar(['All','Instagram','LinkedIn','X'])+`<div class="notice">Drafts and scheduling are saved on your Mac. Direct publishing is awaiting platform connections; a scheduled post will remain queued until publishing is available.</div><div class="cards">${list.map(p=>`<section class="panel"><div class="card-body"><div class="card-top"><div><h2>${esc(p.title)}</h2><div class="row-sub">${esc(p.platform)} · ${esc(p.format)}</div></div>${badge(p.status)}</div></div>${p.format==='Carousel'&&p.slides.length?`<div class="slide-preview">${p.slides.map((s,i)=>`<div class="slide"><small>VAREONHQ / ${String(i+1).padStart(2,'0')}</small>${esc(s)}</div>`).join('')}</div>`:`<div class="post-preview">${esc(p.content||'Your next good idea starts here.')}</div>`}<div class="card-footer"><span>${p.scheduledAt?fmt(p.scheduledAt,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'Unscheduled'}</span><div class="button-row"><button class="text-btn" data-export-post="${p.id}">Export</button><button class="text-btn" data-edit="posts:${p.id}">Edit draft ↗</button></div></div></section>`).join('')}</div>`+(!list.length?panel('Your content studio','Make space for good ideas',empty('megaphone','Start with an idea','Write a post or build a carousel, then give it a place on your calendar.',addButton('posts','Create your first draft'))):'');}
function inbox(){const list=records('emails');const selected=list.find(e=>e.id===selectedMail)||list[0];return heading('CONVERSATIONS THAT MATTER','A calmer kind of inbox.',esc(data.settings.email||'hello@vareonhq.com'),`<div class="button-row"><button class="btn" data-action="sync-mail">${icon('refresh')}Sync Outlook</button><button class="btn" data-action="email-branding">Signature</button>${addButton('emails','Compose')}</div>`)+(!data.connections.outlook?`<div class="notice">Outlook is not connected yet. You can prepare email drafts now. <button class="link" data-page="connections">Connect your mailbox ↗</button></div>`:'')+toolbar(['All','Received','Draft','Sent'])+panel('Your conversations',`${list.length} messages`,list.length?`<div class="mail-layout"><div class="mail-list">${list.map(e=>`<button class="mail-item ${e.id===selected?.id?'active':''}" data-mail="${e.id}"><strong>${esc(e.fromName||e.to||'Draft')}</strong><p>${esc(e.subject)}</p><small>${esc(e.status)} · ${fmt(e.receivedAt||e.createdAt)}</small></button>`).join('')}</div><div class="mail-detail"><h2>${esc(selected.subject)}</h2><div class="mail-meta">${selected.from?'From':'To'}: ${esc(selected.from||selected.to||'Not set')}<br>${esc(clientName(selected.clientId))} · ${fmt(selected.receivedAt||selected.createdAt)}</div>${badge(selected.status)}<div class="mail-body">${esc(selected.body)}</div><div class="button-row" style="margin-top:24px">${selected.status==='Draft'?`<button class="btn" data-edit="emails:${selected.id}">Edit draft</button><button class="btn primary" data-send-email="${selected.id}">Review & send</button>`:selected.status==='Received'?`<button class="btn primary" data-reply="${selected.id}">Reply</button>`:''}</div></div></div>`:empty('mail','A place for every conversation','Connect Outlook to bring your inbox here, or start with a draft.',addButton('emails','Write an email')));}
function automations(){const list=records('automations');return heading('LESS REPETITION. MORE MOMENTUM.','Let the routine take care of itself.','Rules that react to your records, and scheduled work for your assistants.',addButton('automations','New scheduled prompt'))+rulesUI.panel()+`<div class="notice">Local automations run while this app is running and your Mac is awake. Missed recurring runs catch up once when you return. Times are shown in Brisbane time.</div>`+panel('Scheduled work',`${list.filter(j=>j.enabled).length} active automations`,`<div class="panel-body">${list.length?list.map(j=>`<div class="list-row"><div><button class="link" data-edit="automations:${j.id}">${esc(j.name)}</button><div class="row-sub">${esc(j.engine)} · ${esc(j.frequency)} · Next: ${fmt(j.nextRun,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</div>${j.lastError?`<div class="row-sub" style="color:#ad735c">${esc(j.lastError)}</div>`:''}</div><div class="button-row">${badge(j.running?'Running':j.enabled?'Active':'Paused')}<button class="icon-btn" data-toggle-job="${j.id}" aria-label="${j.enabled?'Pause':'Resume'} ${esc(j.name)}">${icon(j.enabled?'pause':'play')}</button><button class="btn small" data-run-job="${j.id}" ${j.running?'disabled':''}>Run now</button></div></div>`).join(''):empty('clock','Make room for the work you love','Schedule a briefing, prepare follow-ups or ask Codex to work on a recurring task.',addButton('automations','Create an automation'))}</div>`)+panel('Run history','Every result, including the things that need attention',`<div class="panel-body">${data.runs.length?data.runs.slice(0,20).map(r=>`<details style="padding:16px 0;border-top:1px solid #edf0e7"><summary style="cursor:pointer;font-size:12px">${esc(r.name)} <span style="float:right">${badge(r.status)}</span><div class="row-sub">${fmt(r.startedAt,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</div></summary><pre class="run-output">${esc(r.output||'Still working…')}</pre></details>`).join(''):empty('check','Your results will appear here','Run an automation to see its outcome.')}</div>`);}
function codex(){return heading('YOUR BUILDING PARTNER','A workspace for getting it done.','Prompt Codex, follow the work and keep the result.',`<button class="btn primary" data-action="focus-codex">${icon('plus')}Ask Codex</button>`)+`<div class="notice">Codex uses its local sign-in and works in this app’s dedicated workspace. Business changes go through dashboard tools; generated files stay in its workspace.</div>`+panel('Codex work','Requests and results',`<div class="panel-body">${data.codexJobs.length?data.codexJobs.map(j=>`<details style="padding:16px 0;border-top:1px solid #edf0e7" ${j.status==='Running'?'open':''}><summary style="cursor:pointer">${esc(j.title)} <span style="float:right">${badge(j.status)}</span></summary><pre class="run-output">${esc(j.output||'Codex is working…')}</pre></details>`).join(''):empty('code','What would you like to build?','Ask Codex to prepare a document, work through a problem or create something for a project.',`<button class="btn soft" data-action="focus-codex">Start a conversation ${icon('arrow')}</button>`)}</div>`);}
function integration(logo,title,description,status,controls){return `<div class="integration"><div class="integration-logo">${logo}</div><h2>${title}</h2><p>${description}</p>${badge(status)}<div class="integration-controls">${controls}</div></div>`;}
function connections(){return heading('YOUR TOOLS, TOGETHER','Everything in its right place.','Connect your accounts and choose how your assistant works.')+(data.settings.outlookError?`<div class="notice">Outlook sign-in needs attention: ${esc(data.settings.outlookError)}<br>For a single-tenant Microsoft registration, enter its tenant ID or verified domain in Set up.</div>`:'')+(data.settings.chatgptError?`<div class="notice">ChatGPT sign-in needs attention: ${esc(data.settings.chatgptError)}</div>`:'')+`<div class="connections-grid">${integration('O','Outlook',esc(data.settings.email||'hello@vareonhq.com')+' · Read, receive, reply and send.',data.connections.outlook?'Connected':'Setup required',`<button class="btn small" data-action="setup-outlook">Set up</button><button class="btn primary small" data-action="connect-outlook">Sign in with Microsoft</button>${data.connections.outlook?'<button class="btn small" data-action="disconnect-outlook">Disconnect</button>':''}`)}${integration('✳','GPT assistant','Use your ChatGPT subscription through OAuth, with web search, business tools and persistent project memory.',data.connections.gpt?'ChatGPT plan connected':'Sign-in required',`<button class="btn small primary" data-action="setup-gpt">${data.connections.gpt?'Manage ChatGPT':'Continue with ChatGPT'}</button>`)}${integration('✦','Claude assistant','Use your Claude subscription through the Claude Code sign-in on this Mac. VareonHQ never sees or stores your Claude credentials.',!data.connections.claude?.installed&&data.connections.claude?'Claude Code not installed':data.connections.claude?.connected?'Claude connected':'Sign-in required',`<button class="btn small primary" data-action="setup-claude">${data.connections.claude?.connected?'Manage Claude':'Sign in with Claude'}</button>`)}${integration('⌥','GitHub (read-only)','Verify repositories, read pull requests, checks and deployments. Public repositories work without a token; private ones need a fine-grained read-only token, kept in macOS Keychain.','Read-only',`<button class="btn small" data-action="setup-github">Manage GitHub</button>`)}${integration('⌘','Codex','Use the Codex account already signed in on this Mac. Requests run in a dedicated workspace.','Local connector ready',`<button class="btn small" data-action="focus-codex">Open workspace</button>`)}${integration('↗','ChatGPT → your dashboard','OAuth and MCP let your existing ChatGPT conversations operate this app. A secure tunnel is required for remote access.',data.settings.publicBaseUrl?'Endpoint configured':'Local endpoint ready',`<button class="btn small" data-action="setup-bridge">Set up OAuth connection</button>`)}${integration('◎','Instagram','Post and carousel drafting is available. Direct publishing needs a Meta developer app and a supported account.','Drafting available',`<button class="btn small" data-page="marketing">Open content studio</button>`)}${integration('in','LinkedIn & X','Plan and prepare posts locally. Direct publishing needs the relevant platform application permissions.','Drafting available',`<button class="btn small" data-page="marketing">Open content studio</button>`)}</div>`+panel('Connection requests','Approve access from ChatGPT only when you started the connection',`<div class="panel-body">${(data.oauthRequests||[]).length?data.oauthRequests.map(r=>`<div class="list-row"><div><h3>${esc(r.clientName)}</h3><div class="row-sub">${esc(r.scope)} · Expires ${fmt(r.expiresAt,{hour:'2-digit',minute:'2-digit'})}</div></div><div class="button-row"><button class="btn small" data-oauth-deny="${r.id}">Deny</button><button class="btn primary small" data-oauth-approve="${r.id}">Allow access</button></div></div>`).join(''):`<p class="sub" style="padding:12px 0">No connection requests waiting.</p>`}</div>`)+panel('Your data','A local database on your Mac',`<div class="panel-body"><p class="sub">Your records are saved in this app’s data folder. Account credentials are stored in macOS Keychain. GPT receives the information it needs when you use it.</p><div class="button-row" style="margin-top:20px"><button class="btn small" data-action="export-data">${icon('download')}Export business records</button></div></div>`);}
function threadMessages(){return data.messages.filter(m=>m.engine===engine&&(m.projectId||'')===workspace.getProjectId()&&(m.conversationId||'')===(currentConversation()?.id||'')).slice().reverse();}
function introHTML(){return `<div class="assistant-intro"><div class="eyebrow">A LITTLE HELP GOES A LONG WAY</div><h2>What’s on your mind today?</h2><p>Talk through an idea, find your next step, or let me take care of something.</p>${['What should I focus on today?','Show me contracts waiting for a signature','Help me plan this week’s content'].map(s=>`<button class="suggestion" data-suggest="${esc(s)}">${s}<span>↗</span></button>`).join('')}<div class="assistant-status"><span class="dot"></span>${engine==='GPT'?(data.connections.gpt?'Signed in to ChatGPT · plan allowance applies.':'Continue with ChatGPT in Connections, or select Codex.'):engine==='Claude'?(data.connections.claude?.connected?'Signed in to Claude · your Claude plan allowance applies.':'Sign in with Claude in Connections, or select another assistant.'):'Using your local ChatGPT sign-in for Codex.'}<br>Your assistant’s changes appear in the workspace.${engine==='GPT'&&!data.connections.gpt?'<div style="margin-top:12px"><button class="btn primary small" data-action="setup-gpt">Continue with ChatGPT</button></div>':engine==='Claude'&&!data.connections.claude?.connected?'<div style="margin-top:12px"><button class="btn primary small" data-action="setup-claude">Sign in with Claude</button></div>':''}</div></div>`;}
function composerHTML(opts={}){return `<div class="assistant-compose"><form id="chat-form"><div class="composer">${chatFilesUI.html()}<textarea id="chat-input" rows="1" aria-label="Message your assistant" placeholder="${esc(opts.placeholder||'Work with '+(engine==='GPT'?'ChatGPT':engine))}" ${busy?'disabled':''}></textarea><div class="composer-footer">${opts.lead||''}<details class="composer-menu composer-add"><summary aria-label="Add context" title="Add context">${icon('plus')}</summary><div class="composer-popover"><button type="button" id="attach-chat-files" ${busy||chatFilesUI.isUploading()?'disabled':''}>${icon('file')}Add files</button><button type="button" id="attach-chat-folder" ${busy||chatFilesUI.isUploading()?'disabled':''}>${icon('folder')}Add folder</button><button type="button" data-page="assets">${icon('folder')}Upload images & videos</button><button type="button" data-new="notes">${icon('file')}Add a business note</button><button type="button" data-page="memory">${icon('spark')}Project memory</button></div></details><details class="composer-menu composer-settings"><summary aria-label="Assistant settings" title="Assistant settings">${icon('shield')}</summary><div class="composer-popover"><label class="engine-select">Assistant<select id="engine" aria-label="Assistant engine" ${busy?'disabled':''}><option ${engine==='GPT'?'selected':''}>GPT</option><option ${engine==='Claude'?'selected':''}>Claude</option><option ${engine==='Codex'?'selected':''}>Codex</option></select></label><button class="speech-toggle" type="button" data-action="toggle-speech" aria-pressed="${speakReplies}">${icon('speaker')}Spoken replies ${speakReplies?'on':'off'}</button><button type="button" id="composer-refresh-models" ${busy?'disabled':''}>${icon('refresh')}Refresh models</button></div></details>${modelControls.html()}<button class="mic" type="button" id="voice-button" aria-label="Start voice conversation" title="Voice input">${icon('mic')}</button>${busy?'<button class="send stop-generation" type="button" id="stop-chat-button" aria-label="Stop assistant" title="Stop assistant"><span class="stop-square" aria-hidden="true"></span></button>':`<button class="send" aria-label="Send message" title="Send message" ${chatFilesUI.isUploading()?'disabled':''}>${icon('send')}</button>`}</div></div></form></div>`;}
function renderAssistant(){const messages=threadMessages();return `<aside class="assistant" aria-label="Business assistant"><div class="assistant-resize-handle" role="separator" tabindex="0" aria-label="Resize assistant" aria-orientation="vertical" title="Drag to resize · double-click to reset"></div><div class="assistant-head"><div class="assistant-brand"><div class="ai-symbol">${icon('chat')}</div><div><strong>Vareon assistant</strong><small>Your business, a conversation away.</small></div></div><div class="assistant-head-actions"><button class="btn small new-chat-button" id="new-chat" ${busy||chatFilesUI.isUploading()?'disabled':''} title="Start a new conversation">${icon('plus')}<span>New chat</span></button><button class="icon-btn" data-action="toggle-assistant" aria-label="Toggle assistant">${icon(assistantOpen?'x':'more')}</button></div></div>${conversationPicker()}<div class="assistant-content" id="chat-scroll">${workspace.contextControls()}<div class="assistant-date">YOUR WORKSPACE COMPANION</div>${messages.length?messages.map(m=>`<div data-message-id="${esc(m.id||'')}" class="chat-message ${m.role==='user'?'user':''} ${m.failed?'error':''}"><small>${m.role==='user'?'YOU':esc(engine.toUpperCase())}</small>${chatFilesUI.history(m)}${historicalChatContent(m)}</div>`).join(''):introHTML()}${workspace.progressHTML()}${busy?'<div class="thinking">Working on it…</div>':''}</div>${composerHTML()}</aside>`;}
async function refresh(){data=await api('/state');busy=!!data.assistantState?.busy;workspace.setWorking(busy);if(busy)engine=data.assistantState.engine||engine;render();}
function bind(){
 bindAssistantLayout();chatFilesUI.bind();
 document.querySelector('#new-chat')?.addEventListener('click',e=>perform(async()=>{const button=e.currentTarget;button.disabled=true;try{await api('/conversations',{method:'POST',body:JSON.stringify({engine,projectId:workspace.getProjectId()})});chatFilesUI.clear();workspace.clearConversation();const input=document.querySelector('#chat-input');if(input)input.value='';await refresh();document.querySelector('#chat-input')?.focus();}catch(error){button.disabled=false;throw error;}}));
 document.querySelector('#chat-conversation')?.addEventListener('change',e=>perform(async()=>{await api('/conversations/'+encodeURIComponent(e.target.value)+'/select',{method:'POST',body:'{}'});workspace.clearConversation();await refresh();}));
 document.querySelector('#composer-refresh-models')?.addEventListener('click',()=>modelControls.refresh());
 document.querySelector('#stop-chat-button')?.addEventListener('click',e=>perform(async()=>{const button=e.currentTarget;button.disabled=true;try{await api('/assistant/stop',{method:'POST',body:'{}'});toast('Stopping the assistant…');}catch(error){button.disabled=false;throw error;}}));
 document.querySelectorAll('.composer-menu').forEach(menu=>menu.addEventListener('toggle',()=>{if(menu.open)document.querySelectorAll('.composer-menu').forEach(other=>{if(other!==menu)other.open=false;});}));
 portfolioUI.bind();rulesUI.bind();bindSidebar();if(page==='chat')chatPage.bind();document.querySelectorAll('[data-module]').forEach(el=>el.onclick=()=>perform(async()=>{const on=el.getAttribute('aria-pressed')!=='true';data.settings.modules=await api('/modules',{method:'PUT',body:JSON.stringify({[el.dataset.module]:on})});render();toast(`${MODULES.find(m=>m.key===el.dataset.module).label} switched ${on?'on':'off'}`);}));document.querySelectorAll('[data-fav]').forEach(el=>el.onclick=e=>{e.stopPropagation();const [kind,id]=el.dataset.fav.split(':'),on=el.getAttribute('aria-pressed')!=='true';perform(async()=>{data.settings.favourites=await api('/favourites',{method:'PUT',body:JSON.stringify({kind,id,on})});render();toast(on?'Pinned to Today':'Unpinned');});});document.querySelectorAll('[data-goto-project]').forEach(el=>el.onclick=()=>{workspace.openProject(el.dataset.gotoProject,el.dataset.gotoTab);page='projects';filter='';search='';render();scrollTo(0,0);});document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page;if(page==='clients')operations.clearClient();filter='';search='';render();history.replaceState(null,'','#'+page);document.querySelector('.content')?.scrollTo({top:0,behavior:'instant'});});
 document.querySelectorAll('[data-new]').forEach(el=>el.onclick=()=>editor(el.dataset.new));
 document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{const[c,id]=el.dataset.edit.split(':');editor(c,data[c].find(r=>r.id===id));});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;activeListViewId='';render();});
 document.querySelectorAll('[data-list-reset]').forEach(el=>el.onclick=()=>{filter='';search='';listCondition='';listCategory='';activeListViewId='';render();});
 document.querySelectorAll('[data-list-condition]').forEach(el=>el.onclick=()=>{listCondition=listCondition===el.dataset.listCondition?'':el.dataset.listCondition;activeListViewId='';render();});
 document.querySelector('#list-category')?.addEventListener('change',e=>{listCategory=e.target.value;activeListViewId='';render();});
 document.querySelector('#list-status')?.addEventListener('change',e=>{filter=e.target.value;activeListViewId='';render();});
 document.querySelectorAll('[data-list-view]').forEach(el=>el.onclick=()=>{const view=(data.listViews||[]).find(v=>v.id===el.dataset.listView);if(!view)return;search=view.query||'';filter=view.status||'';listCategory=view.category||'';listCondition=view.condition||'';activeListViewId=view.id;render();});
 document.querySelectorAll('[data-save-list-view]').forEach(el=>el.onclick=()=>{const name=window.prompt('Name this view');if(!name?.trim())return;perform(async()=>{await api('/records/listViews',{method:'POST',body:JSON.stringify({name:name.trim(),scope:el.dataset.saveListView,query:search,status:filter&&filter!=='All'?filter:'',category:listCategory,condition:listCondition})});await refresh();toast('View saved.');});});
 document.querySelectorAll('[data-remove-list-view]').forEach(el=>el.onclick=()=>{const view=(data.listViews||[]).find(v=>v.id===el.dataset.removeListView);if(!view||!window.confirm(`Remove the saved view “${view.name}”?`))return;perform(async()=>{await api('/records/listViews/'+view.id,{method:'DELETE'});if(activeListViewId===view.id)activeListViewId='';await refresh();toast('Saved view removed.');});});
 document.querySelector('#record-search')?.addEventListener('input',e=>{search=e.target.value;activeListViewId='';const pos=e.target.selectionStart;document.querySelector('#page-content').innerHTML=renderPage();bind();const input=document.querySelector('#record-search');input.focus();input.setSelectionRange(pos,pos);});
 document.querySelectorAll('[data-complete]').forEach(el=>el.onclick=()=>perform(async()=>{const t=data.tasks.find(t=>t.id===el.dataset.complete);await api(`/records/tasks/${t.id}`,{method:'PUT',body:JSON.stringify({...t,status:t.status==='Done'?'To do':'Done'})});await refresh();}));
 document.querySelectorAll('[data-task-project]').forEach(el=>el.onclick=()=>editor('tasks',{projectId:el.dataset.taskProject}));
 document.querySelectorAll('[data-mail]').forEach(el=>el.onclick=()=>{selectedMail=el.dataset.mail;render();});
 document.querySelectorAll('[data-reply]').forEach(el=>el.onclick=()=>{const mail=data.emails.find(m=>m.id===el.dataset.reply);editor('emails',{to:mail.from,subject:'Re: '+mail.subject,clientId:mail.clientId,replyToId:mail.id});});
 document.querySelectorAll('[data-send-email]').forEach(el=>el.onclick=()=>perform(()=>mailUI.review(el.dataset.sendEmail)));
 document.querySelectorAll('[data-review]').forEach(el=>el.onclick=()=>reviewApproval(el.dataset.review));
 document.querySelectorAll('[data-toggle-job]').forEach(el=>el.onclick=()=>perform(async()=>{const j=data.automations.find(j=>j.id===el.dataset.toggleJob);await api(`/records/automations/${j.id}`,{method:'PUT',body:JSON.stringify({...j,enabled:!j.enabled})});await refresh();}));
 document.querySelectorAll('[data-run-job]').forEach(el=>el.onclick=()=>perform(async()=>{await api(`/automations/${el.dataset.runJob}/run`,{method:'POST',body:'{}'});toast('Automation started');await refresh();}));
 document.querySelectorAll('[data-export-post]').forEach(el=>el.onclick=()=>{const p=data.posts.find(p=>p.id===el.dataset.exportPost);download(`${p.title}.txt`,`${p.platform} · ${p.title}\n\n${p.content}\n\n${p.slides.map((s,i)=>`Slide ${i+1}\n${s}`).join('\n\n')}`,'text/plain');});
 document.querySelectorAll('[data-client]').forEach(el=>el.onclick=()=>clientDetail(el.dataset.client));
 document.querySelectorAll('[data-oauth-approve],[data-oauth-deny]').forEach(el=>el.onclick=()=>perform(async()=>{await api(`/oauth-requests/${el.dataset.oauthApprove||el.dataset.oauthDeny}`,{method:'POST',body:JSON.stringify({approve:!!el.dataset.oauthApprove})});await refresh();toast('Connection request updated');}));
 document.querySelectorAll('[data-suggest]').forEach(el=>el.onclick=()=>{document.querySelector('#chat-input').value=el.dataset.suggest;document.querySelector('#chat-input').focus();});
 document.querySelector('#engine')?.addEventListener('change',e=>{engine=e.target.value;localStorage.setItem('vareon-engine',engine);workspace.clearConversation();render();});
 document.querySelector('#chat-form')?.addEventListener('submit',async e=>{e.preventDefault();await sendChat();});
 document.querySelector('#chat-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.querySelector('#chat-form').requestSubmit();}});
 document.querySelector('#voice-button')?.addEventListener('click',startVoice);
 document.querySelectorAll('[data-nav-group]').forEach(el=>el.onclick=()=>showNavigation(el));
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));workspace.bind();services.bind();business.bind();analyticsUI.bind();modelControls.bind();operations.bind();discovery.bind();planningUI.bind();libraryUI.bind();retainersUI.bind();deskUI.bind();businessOpsUI.bind();
 document.querySelector('#phone-page')?.addEventListener('change',e=>{page=e.target.value;filter='';search='';history.replaceState(null,'','#'+page);render();});
}
function bindSidebar(){
 document.querySelector('.nav-search')?.addEventListener('click',()=>commandMenu.show());
 document.querySelectorAll('[data-nav-section]').forEach(el=>el.onclick=()=>{const name=el.dataset.navSection;navOpen[name]=el.getAttribute('aria-expanded')!=='true';saveNavOpen();render();});
 document.querySelectorAll('[data-nav-client]').forEach(el=>el.onclick=()=>{navOpen['client:'+el.dataset.navClient]=el.getAttribute('aria-expanded')!=='true';saveNavOpen();render();});
 document.querySelectorAll('[data-client-nav]').forEach(el=>el.onclick=()=>operations.setClient(el.dataset.clientNav,el.dataset.clientNavTab));
}
async function perform(fn){try{await fn();}catch(error){toast(error.message);}}
async function action(name){await perform(async()=>{
 if(name==='compose'){if(busy)throw new Error('Wait for the current reply or stop it before starting a new chat.');await api('/conversations',{method:'POST',body:JSON.stringify({engine,projectId:workspace.getProjectId()})});chatFilesUI.clear();workspace.clearConversation();page='chat';history.replaceState(null,'','#chat');await refresh();document.querySelector('#chat-input')?.focus();}
 if(name==='toggle-speech'){speakReplies=!speakReplies;if(!speakReplies)speechSynthesis.cancel();render();}
 if(name==='toggle-assistant'){assistantOpen=!assistantOpen;localStorage.setItem('vareon-assistant',assistantOpen?'open':'collapsed');render();}
 if(name==='open-assistant'){assistantOpen=true;localStorage.setItem('vareon-assistant','open');render();document.querySelector('#chat-input').focus();}
 if(name==='focus-codex'){engine='Codex';localStorage.setItem('vareon-engine',engine);assistantOpen=true;render();document.querySelector('#chat-input').focus();}
 if(name==='setup-outlook')setupOutlook();
 if(name==='email-branding')mailUI.branding();
 if(name==='connect-outlook'){const result=await api('/outlook/authorize',{method:'POST',body:'{}'});window.open(result.url,'_blank','noopener');}
 if(name==='disconnect-outlook'){await api('/outlook/disconnect',{method:'POST',body:'{}'});await refresh();}
 if(name==='sync-mail'){await api('/outlook/sync',{method:'POST',body:'{}'});await refresh();toast('Inbox synced');}
 if(name==='setup-gpt')setupGPT();
 if(name==='setup-claude')setupClaude();
 if(name==='setup-github')setupGitHub();
 if(name==='setup-bridge')setupBridge();
 if(name==='export-data')download('vareonhq-backup.json',JSON.stringify(await api('/export'),null,2),'application/json');
 });}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function modal(title,body,wide=false){const kind=wide==='drawer'?'drawer':wide?'wide':'';document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay ${kind==='drawer'?'drawer-overlay':''}"><section class="modal ${kind}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" id="close-modal" aria-label="Close">${icon('x')}</button></div><div class="modal-body">${body}</div></section></div>`;document.querySelector('#close-modal').onclick=closeModal;document.querySelector('.modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal();};document.querySelector('.modal input,.modal textarea,.modal select,.modal button')?.focus();document.querySelector('.modal').addEventListener('keydown',e=>{if(document.querySelector('.modal.live-form')||document.querySelector('#content-preview-root'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const items=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal a')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});}
function closeModal(){document.querySelector('#modal-root').innerHTML='';}
