function datetimeInput(value){if(!value)return '';const p=new Intl.DateTimeFormat('sv-SE',{timeZone:'Australia/Brisbane',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value));return p.replace(' ','T');}
function linkOptions(type,key,record,projectId){const list=(type==='prd'?data.documents||[]:data.tasks||[]).filter(r=>r.id!==record.id&&projectId&&r.projectId===projectId&&(type!=='prd'||r.category==='PRD')),chosen=type==='tickets'?(record[key]||[]):[record[key]];const rows=list.map(r=>`<option value="${esc(r.id)}" ${chosen.includes(r.id)?'selected':''}>${esc((r.ticketKey?r.ticketKey+' · ':'')+(r.title||r.name))}</option>`).join('');return (type==='tickets'?'':'<option value="">None</option>')+(rows||`<option value="" disabled>${projectId?'Nothing to link in this project yet':'Choose a project first'}</option>`)+(type==='tickets'?'':'');}
function requirementOptions(record,prdId){const chosen=record.requirementIds||[],list=(data.requirements||[]).filter(r=>prdId&&r.prdId===prdId&&(r.status!=='Retired'||chosen.includes(r.id))).sort((a,b)=>String(a.code).localeCompare(String(b.code),undefined,{numeric:true}));return list.map(r=>`<option value="${esc(r.id)}" ${chosen.includes(r.id)?'selected':''}>${esc(r.code+' · '+r.title+(r.status==='Retired'?' (retired)':''))}</option>`).join('')||`<option value="" disabled>${prdId?'This PRD has no requirements yet':'Link a PRD first'}</option>`;}
function refreshTicketStatuses(record){const project=document.querySelector('#field-projectId'),status=document.querySelector('#field-status');if(!project||!status)return;const paint=()=>{const allowed=statusesFor(data.projects.find(p=>p.id===project.value)),current=status.value;status.innerHTML=allowed.map(s=>`<option ${s===current?'selected':''}>${esc(s)}</option>`).join('');if(!allowed.includes(current))status.value=allowed.includes('Backlog')&&current==='To do'?'Backlog':allowed.includes('To do')&&['Ready'].includes(current)?'To do':allowed[0];};paint();project.addEventListener('change',paint);}
function refreshTicketLinks(record){refreshTicketStatuses(record);const prd=()=>document.querySelector('#field-prdId'),reqs=()=>document.querySelector('#field-requirementIds'),repaint=()=>{if(reqs()&&prd())reqs().innerHTML=requirementOptions(prd().value===(record.prdId||'')?record:{...record,requirementIds:[]},prd().value);};document.querySelector('#record-form')?.addEventListener('change',e=>{if(e.target.id==='field-prdId'||e.target.id==='field-projectId')repaint();});const project=document.querySelector('#field-projectId');if(!project)return;project.addEventListener('change',()=>{for(const [key,type] of [['prdId','prd'],['parentTaskId','ticket'],['dependencyIds','tickets']]){const el=document.querySelector('#field-'+key);if(!el)continue;const same=project.value===(record.projectId||''),source=same?record:{...record,[key]:type==='tickets'?[]:''};el.innerHTML=linkOptions(type,key,source,project.value);}});}
// Fields most records rarely need sit behind "More fields". It opens by itself when one of them already has a value.
const advanced={tasks:['prdId','requirementIds','requirement','parentTaskId','dependencyIds','implementationPlan','blockedReason','cancelReason','scheduledDate','estimatedHours','clientId'],projects:['plannedCost','startDate'],contracts:['renewalDate','documentUrl'],invoices:['followUpDate','projectId'],documents:['folder','reviewDate','url','version'],prospects:['sourceUrl','followUpAfterDays','followUpPaused','phone'],environments:['providerId','owner','githubEnvironment','notes'],releases:['migrations','notes','commit'],expenses:['clientId'],clients:['phone'],projectTemplates:['notes','description']};
function formFields(collection,record){const extra=advanced[collection]||[],all=fields[collection],basic=all.filter(f=>!extra.includes(f[0])),more=all.filter(f=>extra.includes(f[0])),filled=more.some(([key])=>{const v=record[key];return Array.isArray(v)?v.length:v!==undefined&&v!==''&&v!==0&&v!==false;});return `<div class="form-grid">${basic.map(f=>fieldHTML(collection,f,record)).join('')}</div>${more.length?`<details class="more-fields" ${filled?'open':''}><summary>More fields (${more.length})</summary><div class="form-grid">${more.map(f=>fieldHTML(collection,f,record)).join('')}</div></details>`:''}`;}
function fieldHTML(collection,[key,label,type='text',required=false],record){let value=record[key]??'';if(Array.isArray(value)&&type!=='slides')value=value.join(key==='mediaUrls'?'\n':', ');if(type==='date'&&value)value=String(value).slice(0,10);if(type==='datetime-local'&&value)value=datetimeInput(value);const attrs=`name="${key}" id="field-${key}" ${required?'required':''}`;let input;if(type==='select')input=`<select ${attrs}>${choices[collection][key].map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else if(type==='onboardingTemplate'){input=`<select ${attrs}><option value="">No onboarding checklist</option>${(data.onboardingTemplates||[]).map(t=>`<option value="${esc(t.id)}" ${value===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`;}else if(type==='repository'||type==='environment'){const list=(type==='repository'?data.repositories:data.environments||[]).filter(r=>record.projectId&&r.projectId===record.projectId);input=`<select ${attrs}><option value="">${type==='repository'?'No repository':'Choose an environment'}</option>${list.map(r=>`<option value="${esc(r.id)}" ${value===r.id?'selected':''}>${esc(type==='repository'?r.owner+'/'+r.name:r.name+' · '+r.kind)}</option>`).join('')}</select>`;}else if(type==='requirements'){input=`<select ${attrs} multiple size="4">${requirementOptions(record,record.prdId)}</select><small>Requirements come from the linked PRD. Retired ones are hidden unless already linked.</small>`;}else if(['prd','ticket','tickets'].includes(type)){input=`<select ${attrs} ${type==='tickets'?'multiple size="4"':''}>${linkOptions(type,key,record,record.projectId)}</select><small>Links are limited to the selected project and update when you change it.</small>`;}else if(type==='checkbox')input=`<input ${attrs} type="checkbox" ${value?'checked':''}>`;else if(type==='invoice')input=`<select ${attrs}>${data.invoices.filter(v=>v.status==='Issued').map(v=>`<option value="${v.id}" ${value===v.id?'selected':''}>${esc(v.number||v.title)} · ${currency(v.amount)}</option>`).join('')}</select>`;else if(['client','project','prospect','person'].includes(type))input=`<select ${attrs}><option value="">${type==='person'?'Unassigned':'No '+type}</option>${data[type==='client'?'clients':type==='project'?'projects':type==='person'?'people':'prospects'].filter(v=>type!=='person'||v.status==='Active'||v.id===value).map(v=>`<option value="${v.id}" ${value===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select>`;else if(type==='textarea'||type==='slides')input=`<textarea ${attrs} ${key==='body'?'style="min-height:210px"':''}>${esc(type==='slides'?(record.slides||[]).join('\n---\n'):value)}</textarea>${type==='slides'?'<small>Separate each slide with a line containing --- . A preview appears in the content studio.</small>':''}`;else input=`<input ${attrs} type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''}>`;return `<div class="field ${['textarea','slides','url'].includes(type)?'full':''}"><label for="field-${key}">${label}${required?' *':''}</label>${input}</div>`;}
function editor(collection,record={}){if(collection==='proposals')return proposalsUI.edit(record);record={...({retainers:{status:'Active',startDate:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Brisbane'})},services:{active:true,billing:'One-off',unit:'project'},renewals:{kind:'Other',status:'Active',everyMonths:12,leadDays:30,date:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Brisbane'})},timeEntries:{date:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Brisbane'}),hourlyCost:0,billable:true},meetingNotes:{date:new Date().toLocaleDateString('en-CA',{timeZone:'Australia/Brisbane'})},documents:{category:'Other',status:'Current'},posts:{status:'Draft'},tasks:{status:'To do'},forecastItems:{enabled:true,kind:'Expense',frequency:'Monthly'},reportSchedules:{enabled:true,frequency:'Monthly'}}[collection]||{}),...record};const singular={onboardingTemplates:'onboarding template',renewals:'renewal reminder',timeEntries:'time entry',meetingNotes:'meeting notes',documents:'document',meetings:'meeting',forecastItems:'planned cash flow',reportSchedules:'report schedule',websites:'website',clients:'client',projects:'project',designs:'design reference',services:'service',proposals:'proposal',retainers:'retainer',people:'person',clientAssets:'asset',supportRequests:'support request',tasks:'task',requirements:'requirement',projectStandards:'engineering standard',projectTemplates:'project template',repositories:'repository',environments:'environment',releases:'release',standardExceptions:'exception',contracts:'contract',posts:'content draft',emails:'email draft',automations:'automation',notes:'note',prospects:'prospect',invoices:'invoice',payments:'payment',expenses:'cost',resources:'resource'}[collection];modal(`${record.id?'Edit':'New'} ${singular}${collection==='tasks'&&record.ticketKey?' · '+record.ticketKey:collection==='requirements'&&record.code?' · '+record.code:''}`,`<form id="record-form">${formFields(collection,record)}<div class="form-error hidden" id="form-error"></div><div class="form-actions">${record.id?'<button type="button" class="btn danger" id="delete-record">Delete</button>':''}<button class="btn primary" type="submit">Save ${singular}</button></div></form>`,'drawer');if(collection==='documents')libraryUI.enhanceEditor(record);if(collection==='posts')business.mediaEditor(record);workspace.onEditorOpened(collection,record);if(collection==='tasks')refreshTicketLinks(record);if(collection==='tasks')document.querySelector('#field-status')?.addEventListener('change',e=>{if(['Blocked','Cancelled'].includes(e.target.value)){const more=document.querySelector('.more-fields');if(more){more.open=true;document.querySelector(e.target.value==='Blocked'?'#field-blockedReason':'#field-cancelReason')?.focus();}}});operations.enhanceEditor(collection,record);if(collection==='emails'){document.querySelector('.modal').classList.add('compose-modal','wide');mailUI.enhanceEditor(record);}
// Records open in a side drawer so the list or board stays in view. Composers, post previews and assistant-controlled editors keep the centred dialog.
if(['emails','posts'].includes(collection)||document.querySelector('.modal.live-form')){document.querySelector('.modal')?.classList.remove('drawer');document.querySelector('.modal-overlay')?.classList.remove('drawer-overlay');}document.querySelector('#record-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{let values=Object.fromEntries(new FormData(e.target));if(collection==='releases')values.ticketIds=new FormData(e.target).getAll('ticketIds').filter(Boolean);if(collection==='tasks'){values.dependencyIds=new FormData(e.target).getAll('dependencyIds');values.requirementIds=new FormData(e.target).getAll('requirementIds').filter(Boolean);}if(collection==='emails')values=mailUI.values(values);if(collection==='prospects')values.followUpPaused=document.querySelector('#field-followUpPaused').checked;if(['forecastItems','reportSchedules'].includes(collection))values.enabled=document.querySelector('#field-enabled').checked;if(collection==='timeEntries')values.billable=document.querySelector('#field-billable').checked;if(collection==='contracts')values.depositWaived=document.querySelector('#field-depositWaived').checked;if(collection==='services')values.active=document.querySelector('#field-active').checked;if(collection==='expenses')values.paid=document.querySelector('#field-paid').checked;if(collection==='projectTemplates')values.createStandard=document.querySelector('#field-createStandard').checked;if(collection==='posts'){values.mediaIds=JSON.parse(values.mediaIds||'[]');values.mediaUrls=(values.mediaUrls||'').split('\n').map(s=>s.trim()).filter(Boolean);}if(collection==='posts')values.slides=values.slides?values.slides.split(/^---\s*$/m).map(s=>s.trim()).filter(Boolean):[];for(const key of ['scheduledAt','nextRun','startAt','endAt'])if(values[key])values[key]=new Date(values[key]+':00+10:00').toISOString();if(collection==='automations')values.enabled=record.enabled??true;if(collection==='emails')values.replyToId=record.replyToId||'';await api(`/records/${collection}${record.id?'/'+record.id:''}`,{method:record.id?'PUT':'POST',body:JSON.stringify(values)});closeModal();await refresh();toast('Saved to your workspace');}catch(error){document.querySelector('#form-error').textContent=error.message;document.querySelector('#form-error').classList.remove('hidden');button.disabled=false;}};document.querySelector('#delete-record')?.addEventListener('click',()=>{modal('Delete this record?',`<p class="sub">This removes ${esc(record.name||record.title||record.subject||singular)} from your local workspace.</p><div class="form-actions"><button class="btn" id="cancel-delete">Keep record</button><button class="btn danger" id="confirm-delete">Delete record</button></div>`);document.querySelector('#cancel-delete').onclick=closeModal;document.querySelector('#confirm-delete').onclick=()=>perform(async()=>{await api(`/records/${collection}/${record.id}`,{method:'DELETE',body:'{}'});closeModal();await refresh();toast('Record deleted');});});}
