function setupOutlook(){modal('Connect your Outlook mailbox',`<div class="notice">For hello@vareonhq.com, start with Microsoft sign-in. This requires a one-time Microsoft app registration for your local dashboard. Your GoDaddy mailbox may require administrator consent.</div><ol class="sub"><li>Open <a href="https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade" target="_blank" rel="noopener">Microsoft app registrations</a> and register “VareonHQ Local”.</li><li>Choose the supported accounts for your mailbox.</li><li>Add a <strong>Mobile and desktop application</strong> redirect URI: <code>http://localhost:4317/auth/outlook/callback</code>.</li><li>Enable public client flows. Add delegated permissions User.Read, Mail.ReadWrite, Mail.Send and Contacts.Read.</li><li>Copy its Application (client) ID and Directory (tenant) ID below. For a single-tenant app, use its Directory ID or verified domain instead of common.</li></ol><form id="connection-form"><div class="field"><label for="ms-id">Microsoft application ID</label><input id="ms-id" name="microsoftClientId" value="${esc(data.settings.microsoftClientId||'')}" required pattern="[0-9a-fA-F-]{36}"></div><div class="field" style="margin-top:16px"><label for="ms-tenant">Microsoft tenant ID or verified domain</label><input id="ms-tenant" name="microsoftTenant" value="${esc(data.settings.microsoftTenant||'common')}" placeholder="Directory tenant ID or vareonhq.com" required><small>Single-tenant registrations require their tenant ID or verified domain. Use common only for a multi-tenant registration.</small></div><div class="form-actions"><button class="btn primary">Save setup</button></div></form>`);document.querySelector('#connection-form').onsubmit=e=>{e.preventDefault();perform(async()=>{await api('/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();await refresh();toast('Outlook setup saved. Use Sign in with Microsoft next.');});};}
async function setupGitHub(){modal('GitHub (read-only)','<div class="notice">VareonHQ only reads from GitHub: repositories, branches, pull requests, reviews, checks and deployments. It never pushes, merges or deploys. Public repositories work without a token. For private ones, create a fine-grained token with read-only access to Contents, Pull requests, Checks, Commit statuses, Deployments and Metadata for the repositories you choose.</div><p class="sub" id="github-status">Checking…</p><form id="github-form"><div class="field"><label for="github-token">Fine-grained token</label><input id="github-token" type="password" autocomplete="off" placeholder="github_pat_…"></div><div class="button-row" style="margin-top:16px"><button class="btn primary" type="submit">Save token</button><button class="btn" type="button" id="github-remove">Remove token</button><a class="btn" href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener">Create a token ↗</a></div></form><p class="sub">The token is stored in macOS Keychain and is only sent to api.github.com.</p>');const status=document.querySelector('#github-status');api('/github/status').then(s=>{status.textContent=s.connected?'Connected as '+s.login+'.':s.error?s.error:'No token saved. Public repositories still work.';}).catch(e=>{status.textContent=e.message;});document.querySelector('#github-form').onsubmit=e=>{e.preventDefault();perform(async()=>{const input=document.querySelector('#github-token'),result=await api('/github/token',{method:'PUT',body:JSON.stringify({token:input.value})});input.value='';status.textContent='Connected as '+result.login+'.';toast('GitHub token saved');});};document.querySelector('#github-remove').onclick=()=>perform(async()=>{await api('/github/token',{method:'DELETE'});status.textContent='No token saved. Public repositories still work.';toast('GitHub token removed');});}
async function setupClaude(){const session=data.connections.claude||{};modal('Claude subscription',`<div class="notice">Sign in with Claude to use your Claude plan inside VareonHQ. Sign-in happens in your browser through Claude Code on this Mac, so VareonHQ never receives or stores your Claude credentials and no API key is used.</div><p class="sub">${!session.installed?'Claude Code is not installed on this Mac. Install it from claude.com/claude-code, then reopen this window.':session.connected?'Signed in'+(session.email?' as '+esc(session.email):'')+'.':session.signingIn?'Waiting for you to finish signing in, in your browser.':'Not signed in yet.'}</p><div class="button-row" style="margin-top:20px">${session.installed?`<button class="btn primary" id="connect-claude">${session.connected?'Use a different account':'Sign in with Claude'}</button>`:''}${session.installed?'<button class="btn" id="disconnect-claude">Sign out</button>':''}<a class="btn" href="https://claude.ai/settings/usage" target="_blank" rel="noopener">Manage Claude usage ↗</a></div><p class="sub" style="margin-top:16px">Signing out here also signs out Claude Code on this Mac. If your browser is already signed in to the wrong Claude account, switch accounts on claude.ai in that browser first (or use a private window), then sign in here. Choose the Claude model from the assistant settings in the chat panel.</p>`);document.querySelector('#connect-claude')?.addEventListener('click',()=>perform(async()=>{const result=await api('/claude/sign-in',{method:'POST',body:JSON.stringify({switchAccount:!!session.connected})});toast(result.message);}));document.querySelector('#disconnect-claude')?.addEventListener('click',()=>perform(async()=>{await api('/claude/sign-out',{method:'POST',body:'{}'});closeModal();await refresh();toast('Signed out of Claude.');}));}
async function setupGPT(){const session=data.connections.chatgpt||{};modal('ChatGPT subscription',`<div class="notice">Continue with ChatGPT to authorise VareonHQ to use your eligible ChatGPT plan. This is OAuth sign-in. No API key is requested. Account eligibility and available models are checked by OpenAI.</div><p class="sub">${session.connected?'Signed in as '+esc(session.email||session.name||'your ChatGPT account'):'Not signed in yet.'} ${session.connected&&!session.sharing?'ChatGPT plan usage has not been granted.':''}</p><div class="button-row" style="margin-top:20px"><button class="btn primary" id="connect-chatgpt">Continue with ChatGPT</button>${session.connected?'<button class="btn" id="disconnect-chatgpt">Sign out</button>':''}<a class="btn" href="https://chatgpt.com/#settings/Usage" target="_blank" rel="noopener">Manage ChatGPT usage ↗</a></div><div id="chatgpt-models" style="margin-top:20px"></div><p class="sub">Codex also uses your local ChatGPT sign-in. ChatGPT app conversations and plugin sign-ins are not automatically imported.</p>`);document.querySelector('#connect-chatgpt').onclick=()=>perform(async()=>{const result=await api('/chatgpt/authorize',{method:'POST',body:'{}'});window.open(result.url,'_blank','noopener');toast('Complete ChatGPT sign-in in your browser, then return here.');});document.querySelector('#disconnect-chatgpt')?.addEventListener('click',()=>perform(async()=>{const result=await api('/chatgpt/disconnect',{method:'POST',body:'{}'});closeModal();await refresh();toast(result.message);}));if(session.sharing)perform(async()=>{const models=await api('/chatgpt/models'),target=document.querySelector('#chatgpt-models');if(!target)return;target.innerHTML=`<div class="field"><label for="subscription-model">ChatGPT model</label><select id="subscription-model">${models.map(m=>`<option value="${esc(m.slug)}" ${data.settings.gptModel===m.slug?'selected':''}>${esc(m.name||m.slug)}</option>`).join('')}</select><button class="btn small" id="save-subscription-model">Save model</button></div>`;document.querySelector('#save-subscription-model').onclick=()=>perform(async()=>{await api('/chatgpt/model',{method:'PUT',body:JSON.stringify({model:document.querySelector('#subscription-model').value})});toast('ChatGPT model saved');});});}
function setupBridge(){modal('Let ChatGPT operate your dashboard',`<div class="notice">Your local MCP endpoint and OAuth server are ready. To connect from cloud ChatGPT, first provide an authenticated HTTPS tunnel to this Mac. The dashboard screens remain restricted to your local browser.</div><div class="field"><label>Local MCP endpoint</label><input value="http://localhost:4317/mcp" readonly></div><p class="sub">Configure a tunnel to port 4317, then enter its HTTPS base URL below. Use that URL plus <code>/mcp</code> when adding the custom connection in ChatGPT, and select OAuth. Requests will appear in Connections for your approval.</p><form id="connection-form" style="margin-top:20px"><div class="field"><label for="bridge-url">HTTPS tunnel base URL</label><input id="bridge-url" name="publicBaseUrl" type="url" placeholder="https://your-private-bridge.example" value="${esc(data.settings.publicBaseUrl||'')}" required></div><div class="form-actions"><button class="btn primary">Save connection URL</button></div></form><div class="hr"></div><button class="btn small danger" id="revoke-access">Revoke all ChatGPT access</button>`);document.querySelector('#connection-form').onsubmit=e=>{e.preventDefault();perform(async()=>{await api('/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();await refresh();toast('Connection URL saved');});};document.querySelector('#revoke-access').onclick=()=>perform(async()=>{await api('/oauth/revoke',{method:'POST',body:'{}'});toast('All ChatGPT access revoked');});}
function oldReviewEmail(id){const email=data.emails.find(e=>e.id===id);modal('Review email before sending',`<div class="notice">This sends from ${esc(data.settings.email)} through your connected Outlook account.</div><h3>${esc(email.subject)}</h3><p class="sub">To: ${esc(email.to||'No recipient')}</p><div class="mail-body">${esc(email.body)}</div><div class="form-actions"><button class="btn primary" id="confirm-send" ${!email.to?'disabled':''}>Send email</button></div>`);document.querySelector('#confirm-send').onclick=async e=>{e.target.disabled=true;await perform(async()=>{await api(`/emails/${id}/send`,{method:'POST',body:'{}'});closeModal();await refresh();toast('Outlook accepted the email for sending');});e.target.disabled=false;};}
function reviewApproval(id){perform(()=>operations.review(id));}

async function sendChat(value,extraContext={}){const input=document.querySelector('#chat-input');if(busy||chatFilesUI.isUploading())return;const prompt=value||input.value.trim()||(chatFilesUI.hasDraft()?'Please review the attached files.':'');if(!prompt)return;const attached=chatFilesUI.take();input.value='';busy=true;workspace.start();const projectId=workspace.getProjectId();data.messages.unshift({role:'user',content:prompt,engine,projectId,attachments:attached.files,conversationId:currentConversation()?.id||''});render();try{const result=await api('/assistant',{method:'POST',body:JSON.stringify({prompt,engine,projectId,conversationId:currentConversation()?.id||'',uiContext:{...workspace.viewContext(),clientId:page==='clients'?operations.getClientId():'',...extraContext},fileIds:attached.files.map(f=>f.id)})});if(speakReplies&&'speechSynthesis' in window){const spoken=new SpeechSynthesisUtterance(result.content);spoken.lang='en-AU';const localVoice=speechSynthesis.getVoices().find(v=>v.localService&&v.lang.startsWith('en'));if(localVoice)spoken.voice=localVoice;speechSynthesis.speak(spoken);}}catch(error){chatFilesUI.restore(attached);toast(error.message);}finally{busy=false;workspace.finish();await refresh();const scroll=document.querySelector('#chat-scroll');if(scroll)scroll.scrollTop=999999;}}

let voiceActive=false,voiceRecognizer;
async function startVoice(){if(voiceActive){voiceRecognizer?.stop();return;}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Use Mac Dictation in the message box: press your Dictation shortcut (usually Fn twice), or choose Edit → Start Dictation. No API key is needed.');document.querySelector('#chat-input')?.focus();return;}voiceRecognizer=new Recognition();voiceRecognizer.lang='en-AU';voiceRecognizer.interimResults=true;voiceRecognizer.onresult=event=>{document.querySelector('#chat-input').value=[...event.results].map(r=>r[0].transcript).join(' ');document.querySelector('#chat-input').dispatchEvent(new Event('input'));};voiceRecognizer.onend=()=>{voiceActive=false;document.querySelector('#voice-button')?.classList.remove('recording');toast('Review your voice message, then send it.');};voiceRecognizer.onerror=event=>{voiceActive=false;toast('Voice input is unavailable: '+event.error+'. You can use Mac Dictation in the message box.');};voiceRecognizer.start();voiceActive=true;document.querySelector('#voice-button')?.classList.add('recording');}
