refresh().then(()=>api('/outlook/auto-sync',{method:'POST',body:JSON.stringify({reason:'load'})}).catch(()=>null)).then(()=>{if(!workspace.dirty()&&!busy&&!document.activeElement?.matches('input,textarea,select'))return refresh();}).catch(e=>{document.querySelector('#app').innerHTML=`<div class="error-panel">Could not open your workspace: ${esc(e.message)}<br>Check that the local app is running, then reload.</div>`;});
setInterval(async()=>{if(page==='build'||document.querySelector('#nav-flyout')||document.querySelector('.composer-menu[open]')||document.querySelector('.modal')||document.body.classList.contains('resizing-assistant')||document.activeElement?.matches('input,textarea,select')||voiceActive||workspace.dirty()||busy)return;try{data=await api('/state');render();}catch{}},7000);
const livePreview=new EventSource('/api/events');
livePreview.onmessage=event=>{if(event.data==='reload'&&!chatFilesUI.hasDraft()&&!document.querySelector('.modal')&&!document.querySelector('#chat-input')?.value&&!voiceActive&&!workspace.dirty()&&!busy)location.reload();};

livePreview.onerror=()=>{fetch('/').catch(()=>{});};

livePreview.addEventListener('workspace',event=>{try{const value=JSON.parse(event.data);workspace.onEvent(value);business.onEvent(value);operations.onEvent(value);if(value.type==='account_changed')refresh();if(value.type==='mail_sync'&&!workspace.dirty()&&!busy&&!document.querySelector('.modal')&&!document.activeElement?.matches('input,textarea,select'))refresh().catch(()=>{});if(value.type==='assistant_started'){busy=true;refresh().catch(()=>{});}if(value.type==='assistant_finished'){busy=false;refresh();}}catch{}});

document.addEventListener('click',event=>{document.querySelectorAll('.composer-menu[open]').forEach(menu=>{if(!menu.contains(event.target))menu.open=false;});});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.composer-menu[open]').forEach(menu=>menu.open=false);});

document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')api('/outlook/auto-sync',{method:'POST',body:JSON.stringify({reason:'due'})}).catch(()=>{});});
// Safari's keyboard changes the visible viewport independently of the layout viewport.
function updatePhoneViewport(){if(innerWidth<=700)document.documentElement.style.setProperty('--phone-height',Math.min(innerHeight,window.visualViewport?.height||innerHeight)+'px');else document.documentElement.style.removeProperty('--phone-height');}
window.visualViewport?.addEventListener('resize',updatePhoneViewport);window.addEventListener('resize',updatePhoneViewport);updatePhoneViewport();
